	return kopf('Zuordnung unklar – bitte entscheiden', vorgangsId, mail) +
		`<br>Grund: ${esc(zuordnung.grund)}<br>Kandidaten:<ul>${kand}</ul>Bitte die Mail einem Kandidaten zuordnen oder als neuen Vorgang bestätigen.` +
