	return teile.join('<br><br>');
}

function meldungExtraktionFehlgeschlagen(vorgangsId, mail, fehlercode) {
	return kopf('Datenextraktion fehlgeschlagen – bitte manuell bearbeiten', vorgangsId, mail) +
