	if (begruendung) z.push(`Einschätzung der KI: ${esc(begruendung)}`);
	const stellen = verdaechtigeStellen(m);
	if (stellen.length) z.push('Auffällige Stellen:<ul>' + stellen.map((s) => `<li>${esc(s.wo)}: „${esc(s.text)}“</li>`).join('') + '</ul>');
